export const MONUMENTS = JSON.parse("[{\"id\":\"n1612810138\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"И. Ф. Крузенштерн\",\"x\":-3984.4,\"z\":-241.8,\"material\":\"bronze\",\"subject\":\"Q160888\",\"inscription\":\"Первому русскому плавателю вокруг света адмиралу Ивану Федоровичу Крузенштерну\",\"wikidata\":\"Q66124832\",\"wikipedia\":\"ru:Памятник И. Ф. Крузенштерну\"},{\"id\":\"n8754362395\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-4005,\"z\":-276.6,\"subject\":\"Q1394\",\"inscription\":\"В этом здании 8 (21) мая 1917 года на общегородском собрании Петроградской партийной организации выступал Владимир Ильич Ленин с докладом об итогах седьмой (Апрельской) Всероссийской конференции РСДРП(б)\"},{\"id\":\"n8754362396\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-4028.9,\"z\":-262.9,\"inscription\":\"Здесь учились видные советские адмиралы: адмирал флота Советского Союза Кузнецов Николай Герасимович с 1922 по 1926 г., адмирал Трибуц Владимир Филиппович с 1922 по 1926 г., адмирал Октябрьский Филипп Сергеевич, адмирал флота Лобов Семен Михайлович\"},{\"id\":\"n8754362397\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-4031.7,\"z\":-261.3,\"inscription\":\"Здесь учились видные советские адмиралы: адмирал Галлер Лев Михайлович с 1902 по 1905 г., адмирал Левченко Гордей Иванович с 1918 по 1922 г., адмирал Алафузов Владимир Антонович с 1921 по 1925 г., адмирал Владимирский Лев Анатольевич с 1921 по 1925 г.\"},{\"id\":\"n8754362398\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-4053.4,\"z\":-248.9,\"inscription\":\"Здесь учились выдающиеся деятели науки: с 1814 по 1819 г.г. Даль Владимир Иванович, с 1838 по 1842 г.г. Можайский Александр Федорович, с 1873 по 1877 г.г. Шокальский Юлий Михайлович, с 1878 по 1884 г.г. Крылов Алексей Николаевич\"},{\"id\":\"n8754362399\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-4056,\"z\":-247.5,\"inscription\":\"Здесь учились выдающиеся русские флотоводцы: адмирал Спиридов Григорий Андреевич с 1725 по 1732 г.г., адмирал Ушаков Федор Федорович с 1761 по 1766 г., адмирал Сенявин Дмитрий Николаевич, адмирал Нахимов Павел Степанович, адмирал Бутаков Григорий Иванович\"},{\"id\":\"n8754362400\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-4061.7,\"z\":-244.2},{\"id\":\"n5895167864\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. Х. Бумагину\",\"x\":-3099.5,\"z\":-250.6,\"subject\":\"Q39083070\",\"inscription\":\"В этом доме жил Григорий Харитонович Бумагин, секретарь Ленинградского обкома ВКП(б) в годы Великой Отечественной войны, один из руководителей партизанского движения в Ленинградской области\"},{\"id\":\"n6088743387\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Памятный знак\",\"x\":-4986.3,\"z\":-203.5,\"inscription\":\"В этом здании работал выпускник юридического факультета Санкт-Петербургского государственного университета доктор юридических наук, профессор, первый мэр Санкт-Петербурга Анатолий Александрович Собчак\"}]");
